"""Option B — "a través del visor". Music + SFX generated by code (no samples).

Reuses the instruments, BS.1770 meter, ducking and true-peak limiter from
compose.py; only the arrangement changes. Timing from src/timeline/cuesB.json.

Writes public/audio/sony-scala-mix-b.wav, music-b.wav, sfx-b.wav and
audio-src/loudness-report-b.md.   Usage: python3 -I audio-src/compose_b.py <project>
"""
import json
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import numpy as np  # noqa: E402
from scipy.io import wavfile  # noqa: E402

import compose as A  # noqa: E402
from compose import (  # noqa: E402
    BEAT, N, SR, band_noise, beep, blip, butter, clap, convolve_st, filt, fm_bell, fs, hat, kick, mtof, pad_note,
    place, place_st, pluck, polyblep_saw, reverb_ir, shimmer, shutter_curtain, snare, soft_clip, sub_drop, tsec,
    tv_lowpass, whoosh,
)

CHORDS = [  # (start s, end s, pad voicing, bass midi, name)
    (0.0, 1.5, [62, 66, 69, 73], 35, "Bm9"),
    (1.5, 2.0, [62, 66, 69, 73], 35, "Bm9"),
    (2.0, 4.0, [62, 66, 67, 71], 31, "Gmaj7"),
    (4.0, 6.0, [57, 62, 66, 69], 30, "D/F#"),
    (6.0, 7.5, [61, 64, 69, 73], 33, "A"),
    (7.5, 10.0, [62, 66, 69, 73], 35, "Bm9"),
    (10.0, 12.0, [62, 66, 67, 71], 31, "Gmaj7"),
    (12.0, 13.0, [62, 64, 69, 74], 33, "Asus4"),
    (13.0, 15.0, [61, 64, 66, 69, 74], 38, "Dmaj9"),
]


def impact(gain: float = 1.0, seed: int = 0) -> np.ndarray:
    n = int(1.2 * SR)
    t = np.arange(n) / SR
    boom = A.sine_sweep(42 + 90 * np.exp(-t / 0.04)) * np.exp(-t / 0.35)
    crack = filt(np.random.default_rng(seed).standard_normal(n), butter("bandpass", [300, 6000])) * np.exp(-t / 0.025)
    return soft_clip(boom + 0.45 * crack, 1.5) * gain


def shutter_click(seed: int) -> np.ndarray:
    """Short shutter for the 30 fps burst (one per video frame)."""
    rng = np.random.default_rng(seed)
    n = int(0.03 * SR)
    t = np.arange(n) / SR
    tk = filt(rng.standard_normal(n), butter("bandpass", [1500, 9000])) * np.exp(-t / 0.0022)
    body = np.sin(2 * np.pi * (2100 + rng.uniform(-80, 80)) * t) * np.exp(-t / 0.006)
    return 0.8 * tk + 0.3 * body


def build_music(B: dict) -> np.ndarray:
    t_all = np.arange(N) / SR
    drop = tsec(B["hook"]["shutter"])  # 1.5 s
    slams = [tsec(f) for f in B["kinetic"]["words"]]  # 7.5, 7.733, 8.0
    end_in = tsec(B["end"]["in"])  # 10.0
    hit = tsec(B["end"]["shutter"])  # 13.0

    pad = np.zeros((N, 2))
    xf = int(0.05 * SR)
    for ci, (a, b, notes, _, _) in enumerate(CHORDS):
        s0 = int(a * SR)
        n = min(int((b - a) * SR) + (int(2.0 * SR) if ci == len(CHORDS) - 1 else xf), N - s0)
        seg = sum(pad_note(m, n, seed=500 + 10 * ci + k) for k, m in enumerate(notes)) / np.sqrt(len(notes))
        env = np.ones(n)
        env[:xf] = np.linspace(0, 1, xf)
        if ci < len(CHORDS) - 1:
            env[-xf:] *= np.linspace(1, 0, xf)
        place_st(pad, seg * env[:, None], s0)
    keys = [(0, 380), (1.4, 900), (1.5, 3600), (7.45, 3600), (7.5, 1400), (9.0, 700), (10.0, 3000), (12.9, 2600), (13.0, 3600), (15, 900)]
    pad = tv_lowpass(pad, np.interp(t_all, [k[0] for k in keys], [k[1] for k in keys]))
    pad *= np.interp(t_all, [0, 0.3, 1.45, 1.5, 7.45, 7.5, 9.0, 10.0, 12.85, 13.0, 15.0],
                     [0.0, 0.5, 0.6, 0.85, 0.85, 0.35, 0.35, 0.8, 0.5, 1.0, 1.0])[:, None] * 0.5

    groove = [(drop, slams[0]), (end_in, hit - 0.25)]
    bass = np.zeros((N, 2))
    arp = np.zeros((N, 2))
    drums = np.zeros((N, 2))
    kicks: list[float] = []
    for a, b in groove:
        for st in np.arange(a, b - 1e-6, BEAT / 2):
            ch = next(c for c in CHORDS if c[0] <= st < c[1])
            n = int(BEAT / 2 * 0.9 * SR)
            t = np.arange(n) / SR
            f = mtof(ch[3])
            e = np.clip(t / 0.004, 0, 1) * np.exp(-t / 0.15)
            place(bass, (np.sin(2 * np.pi * f * t) * 0.55 + filt(polyblep_saw(np.full(n, 2 * f)), butter("lowpass", 450)) * 0.45) * e, int(st * SR))
        for i, st in enumerate(np.arange(a, b - 1e-6, BEAT / 4)):
            ch = next(c for c in CHORDS if c[0] <= st < c[1])
            tones = sorted(ch[2]) + [sorted(ch[2])[1] + 12]
            m = tones[[0, 2, 1, 3, 4, 3, 1, 2][i % 8] % len(tones)] + 12
            place(arp, pluck(m, 0.35, bright=1.5) * (0.8 + 0.2 * (i % 4 == 0)), int(st * SR), pan=0.4 if i % 2 else -0.4)
            off = i % 4 == 2
            place(drums, hat(0.8 if off else 0.3, open_=(off and i % 16 == 14)), int(st * SR), pan=0.2 if i % 2 else -0.2, gain=0.5)
        for st in np.arange(a, b - 1e-6, BEAT):
            kicks.append(st)
            place(drums, kick(), int(st * SR), gain=0.66)
            if int(round((st % 2.0) / BEAT)) in (1, 3):
                place(drums, clap(), int(st * SR), gain=0.55)
    # delay on the arp
    d = int(0.375 * SR)
    mono = arp.sum(axis=1) * 0.5
    for k in range(1, 5):
        arp[k * d:, k % 2] += mono[: N - k * d] * 0.38 ** k
    arp *= 0.42

    # hook: low drone + riser into the first shutter
    n = int(drop * SR)
    t = np.arange(n) / SR
    place(bass, np.sin(2 * np.pi * mtof(35) * t) * np.clip(t / 0.05, 0, 1) * 0.5, 0)
    x = np.linspace(0, 1, int(0.7 * SR))
    place(drums, band_noise(len(x), 600 * (8000 / 600) ** x, np.full(len(x), 0.7), x ** 2.5, seed=301) * 0.8, int((drop - 0.7) * SR))
    # snare roll into the slams
    rt, t0 = [], 6.5
    while t0 < slams[0] - 0.01:
        rt.append(t0)
        t0 += BEAT / 4 if t0 < 7.0 - 1e-9 else BEAT / 8
    for i, st in enumerate(rt):
        place(drums, snare(0.25 + 0.75 * (i / len(rt)) ** 1.5, 180 + 100 * i / len(rt)), int(st * SR), gain=0.6)
    # stop-time slams: band hit + chord stab
    hall = reverb_ir(2.2, 0.6)
    for k, st in enumerate(slams):
        place(drums, kick(1.2), int(st * SR), gain=0.8)
        place(drums, clap(1.2), int(st * SR), gain=0.6)
        stab = sum(pluck(m, 0.8, bright=2.2) for m in [59, 62, 66, 69, 74]) * 0.6
        place_st(drums, convolve_st(stab, hall) * 0.5 + np.stack([stab, stab], 1) * 0.5, int(st * SR))
    # rebuild into the end card
    x = np.linspace(0, 1, int(1.0 * SR))
    place(drums, band_noise(len(x), 300 * (9000 / 300) ** x, np.full(len(x), 0.7), x ** 2.6, seed=302) * 0.7, int((end_in - 1.0) * SR))
    # final hit 13.0: Dmaj9 bells + sub + reverse swell
    bells = np.zeros((N, 2))
    hs = int(hit * SR)
    for k, m in enumerate([74, 78, 81, 85, 88]):
        place(bells, fm_bell(m, 2.0), hs + int(k * 0.028 * SR), pan=-0.5 + 0.25 * k, gain=0.55)
    sw = int(0.6 * SR)
    x = np.linspace(0, 1, sw)
    place(bells, band_noise(sw, 2500 * (7000 / 2500) ** x, np.full(sw, 1.2), x ** 3.2, seed=303) * 0.9, hs - sw)
    place(bells, sub_drop(66, 27, 1.9, 0.7), hs, gain=0.6)

    sc = np.zeros(N)
    for kt in kicks:
        s = int(kt * SR)
        n = min(int(0.3 * SR), N - s)
        tt = np.arange(n) / SR
        sc[s:s + n] = np.maximum(sc[s:s + n], np.clip(tt / 0.003, 0, 1) * np.exp(-tt / 0.11))
    pad *= (1 - 0.5 * sc)[:, None]
    bass *= (1 - 0.6 * sc)[:, None]
    music = pad + bass + arp + drums + bells
    music += convolve_st(pad * 0.25 + arp * 0.3 + bells * 0.6, reverb_ir(3.0, 0.85)) * 0.5
    return music


def build_sfx(B: dict) -> tuple[np.ndarray, list]:
    sfx = np.zeros((N, 2))
    ev: list = []
    H, R, S, K, E = B["hook"], B["burst"], B["split"], B["kinetic"], B["end"]
    for i, f in enumerate(H["words"]):
        place(sfx, impact(1.0, seed=10 + i), fs(f), gain=0.9)
        ev.append((["impacto ENFOCA.", "impacto DISPARA."][i], f))
    for k, (f, x, _) in enumerate(H["af"]):
        place(sfx, blip(2600, 2900, 0.04), fs(f), pan=(x - 540) / 600, gain=0.4)
    ev.append(("AF buscando (5 saltos)", H["af"][0][0]))
    for k in range(2):
        place(sfx, beep(3150, 0.045), fs(H["afLock"]) + int(k * 0.085 * SR), gain=0.45)
    ev.append(("bip AF fijado (doble 3150 Hz)", H["afLock"]))
    place(sfx, shutter_curtain(71, 1.0), fs(H["shutter"]), gain=0.9)
    place(sfx, shutter_curtain(72, 1.1), fs(H["shutter"]) + int(0.055 * SR), gain=0.75)
    ev.append(("obturador (2 cortinas) + flash", H["shutter"]))
    for i in range(R["count"]):
        place(sfx, shutter_click(900 + i), fs(R["start"] + i), pan=0.35 * np.sin(i * 2.1), gain=0.75)
    ev.append(("ráfaga: 30 obturadores en 1 s", R["start"]))
    place(sfx, shimmer(0.6, 4200, seed=31), fs(R["fpsLabel"]), gain=0.55)
    ev.append(("brillo «30 fps»", R["fpsLabel"]))
    place(sfx, whoosh(tsec(R["exit"] - 4 + 16) - tsec(R["exit"] - 4), 300, 6000, peak=0.5, seed=32), fs(R["exit"] - 4), gain=0.8)
    ev.append(("whoosh salen las fotos", R["exit"], R["exit"]))
    n = int(tsec(S["inDur"] + 6) * SR)
    place(sfx, whoosh(n / SR, 250, 4500, peak=0.45, seed=33), fs(S["in"]), pan=np.linspace(-0.8, 0.3, n), gain=0.7)
    place(sfx, whoosh(n / SR, 250, 4500, peak=0.45, seed=34), fs(S["in"] + 3), pan=np.linspace(0.8, -0.3, n), gain=0.7)
    ev.append(("whoosh pantalla dividida", S["in"], S["in"] + 3))
    place(sfx, blip(1500, 1900), fs(S["badge"]), gain=1.4)
    place(sfx, shimmer(0.45, 3600, seed=37), fs(S["badge"]), gain=0.5)
    ev.append(("blip «N.º 1 en ventas»", S["badge"]))
    place(sfx, whoosh(0.5, 300, 5000, peak=0.4, seed=35), fs(S["exit"]), gain=0.7)
    ev.append(("whoosh se abre la pantalla", S["exit"], S["exit"] + 2))
    for i, f in enumerate(K["words"]):
        place(sfx, impact(1.0, seed=40 + i), fs(f), gain=0.9)
    ev.append(("golpe PRUÉBALAS", K["words"][0]))
    ev.append(("golpe EN TUS", K["words"][1]))
    ev.append(("golpe MANOS.", K["words"][2]))
    place(sfx, whoosh(0.5, 400, 7000, peak=0.35, seed=36), fs(K["exit"]), gain=0.7)
    ev.append(("whoosh palabras arriba", K["exit"], K["exit"] + 2))
    for k, (f, x, _) in enumerate(E["af"]):
        place(sfx, blip(2600, 2900, 0.06), fs(f), pan=(x - 540) / 600, gain=1.1)
    ev.append(("AF buscando la tienda", E["af"][0][0]))
    for k in range(2):
        place(sfx, beep(3150, 0.045), fs(E["afLock"]) + int(k * 0.085 * SR), gain=0.45)
    ev.append(("bip AF fijado en Scala", E["afLock"]))
    wn = int(0.5 * SR)
    t = np.arange(wn) / SR
    place(sfx, A.sine_sweep(1800 * (8800 / 1800) ** (t / t[-1]) ** 1.4) * (t / t[-1]) ** 2.5 * 0.15, fs(E["shutter"]) - wn, gain=0.8)
    place(sfx, shutter_curtain(81, 1.0), fs(E["shutter"]), gain=0.95)
    place(sfx, shutter_curtain(82, 1.1), fs(E["shutter"]) + int(0.055 * SR), gain=0.8)
    place(sfx, impact(1.0, seed=50), fs(E["shutter"]), gain=0.8)
    ev.append(("obturador final + golpe", E["shutter"]))
    return sfx, ev


def main(project: str) -> None:
    proj = Path(project)
    B = json.loads((proj / "src/timeline/cuesB.json").read_text())
    music, (sfx, events) = build_music(B), build_sfx(B)
    dc = butter("highpass", 18.0)
    music, sfx = filt(music, dc), filt(sfx, dc)
    music *= 10 ** ((-22.0 - A.integrated_lufs(music)) / 20)
    sfx *= 10 ** ((-19.0 - A.integrated_lufs(sfx)) / 20)
    music_d, duck = A.duck_music(music, sfx, -7.0)
    t = np.arange(N) / SR
    fade = np.where(t > 14.35, np.cos(np.clip((t - 14.35) / 0.63, 0, 1) * np.pi / 2) ** 2, 1.0)
    music_d *= fade[:, None]
    sfx *= fade[:, None]
    mix = music_d + sfx
    gain = 10 ** ((A.TARGET_LUFS - A.integrated_lufs(mix)) / 20)
    for _ in range(8):
        g_lim = A.limiter_gain(mix * gain, A.CEILING_DBTP - 0.5)
        err = A.TARGET_LUFS - A.integrated_lufs(mix * gain * g_lim[:, None])
        if abs(err) < 0.02:
            break
        gain *= 10 ** (err / 20)
    curve = (gain * g_lim)[:, None]

    def to16(x: np.ndarray, seed: int) -> np.ndarray:
        rng = np.random.default_rng(seed)
        y = np.clip(np.round((x + (rng.random(x.shape) - rng.random(x.shape)) / 32768.0) * 32767.0), -32768, 32767).astype(np.int16)
        y[-int(0.02 * SR):] = 0
        return y

    out = proj / "public/audio"
    mix16 = to16(mix * curve, 11)
    wavfile.write(out / "sony-scala-mix-b.wav", SR, mix16)
    wavfile.write(out / "music-b.wav", SR, to16(music_d * curve, 12))
    wavfile.write(out / "sfx-b.wav", SR, to16(sfx * curve, 13))

    m = mix16.astype(float) / 32768.0
    mu = (music_d * curve)
    sf = (sfx * curve)
    lines = [
        "# Loudness report — sony-scala-mix-b.wav (opción B)",
        "",
        f"- Integrado BS.1770-4: **{A.integrated_lufs(m):.2f} LUFS** · true peak **{A.true_peak_dbtp(m):.2f} dBTP** · "
        f"últimos 20 ms: {A.db(np.max(np.abs(m[-960:])) + 1e-12):.0f} dBFS",
        "",
        "| frame | t (s) | evento | música | sfx | mezcla | ducking |",
        "|---:|---:|---|---:|---:|---:|---:|",
    ]
    for e in sorted(events, key=lambda e: e[1]):
        s = fs(e[2] if len(e) > 2 else e[1])
        g = 20 * np.log10(duck[min(s + int(0.05 * SR), N - 1)])
        lines.append(f"| {e[1]} | {e[1] / 30:.2f} | {e[0]} | {A.momentary_lufs(mu, s):.1f} | {A.momentary_lufs(sf, s):.1f} | "
                     f"{A.momentary_lufs(m, s):.1f} | {g:.1f} dB |")
    (proj / "audio-src/loudness-report-b.md").write_text("\n".join(lines) + "\n")
    print("\n".join(lines))


if __name__ == "__main__":
    main(sys.argv[1] if len(sys.argv) > 1 else ".")
